import React from 'react';
import { useNavigate } from 'react-router-dom';
import './MainDashboard.css';

const MainDashboard = () => {
    const navigate = useNavigate();

    const pages = [
        {
            title: 'Customer Shop',
            description: 'Browse products and place orders',
            icon: '🛒',
            path: '/shop',
            color: '#2196F3'
        },
        {
            title: 'Inventory Manager',
            description: 'Add/update products and track stock',
            icon: '📦',
            path: '/inventory-manager',
            color: '#4CAF50'
        },
        {
            title: 'Purchase Orders',
            description: 'Generate orders for low stock items',
            icon: '📋',
            path: '/purchase-orders',
            color: '#FF5722'
        },
        {
            title: 'Dashboard',
            description: 'View analytics and reports',
            icon: '📊',
            path: '/dashboard',
            color: '#FF9800'
        },
        {
            title: 'Inventory',
            description: 'View inventory details',
            icon: '📋',
            path: '/inventory',
            color: '#9C27B0'
        },
        {
            title: 'Orders',
            description: 'Manage customer orders',
            icon: '📝',
            path: '/orders',
            color: '#F44336'
        },
        {
            title: 'Suppliers',
            description: 'Manage supplier information',
            icon: '🏭',
            path: '/suppliers',
            color: '#00BCD4'
        }
    ];

    return (
        <div className="main-dashboard">
            <header className="dashboard-header">
                <h1>Inventory Management System</h1>
                <p className="subtitle">Select a module to get started</p>
            </header>

            <div className="dashboard-grid">
                {pages.map((page, index) => (
                    <div
                        key={index}
                        className="dashboard-card"
                        onClick={() => navigate(page.path)}
                        style={{ borderTop: `4px solid ${page.color}` }}
                    >
                        <div className="card-icon" style={{ color: page.color }}>
                            {page.icon}
                        </div>
                        <h2>{page.title}</h2>
                        <p>{page.description}</p>
                        <div className="card-arrow" style={{ color: page.color }}>→</div>
                    </div>
                ))}
            </div>

            <footer className="dashboard-footer">
                <p>© 2025 Inventory Management System</p>
            </footer>
        </div>
    );
};

export default MainDashboard;
